/**
 * Matches a tool's hostname to a Simple Icons brand logo, so users never have to
 * supply icons. The index is generated by scripts/build-brand-icons.mjs into
 * /public/brand-icons/index.json. No network calls to the tool's site.
 */

export type BrandIconIndex = {
  version: string;
  /** Every available logo, served as /brand-icons/<slug>.svg. */
  slugs: string[];
  /** Other spellings (normalised titles, "aka" names) → slug, e.g. nextjs → nextdotjs. */
  aliases: Record<string, string>;
};

/** Lookup key for a brand title or domain label. Keep in sync with scripts/build-brand-icons.mjs. */
export function brandKey(value: string): string {
  return value
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/\+/g, "plus")
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]/g, "");
}

/** Hosting platforms: `someone.vercel.app` is someone's project, not Vercel. */
const PLATFORM_SUFFIXES = [
  "github.io",
  "gitlab.io",
  "vercel.app",
  "netlify.app",
  "pages.dev",
  "workers.dev",
  "deno.dev",
  "web.app",
  "firebaseapp.com",
  "herokuapp.com",
  "onrender.com",
  "fly.dev",
  "up.railway.app",
  "glitch.me",
  "replit.app",
  "repl.co",
  "surge.sh",
  "azurewebsites.net",
  "cloudfront.net",
  "amplifyapp.com",
  "supabase.co",
  "webflow.io",
  "framer.website",
  "notion.site",
  "streamlit.app",
  "hf.space",
] as const;

/** `bbc.co.uk`, `example.com.au`: the brand is the label before these. */
const COUNTRY_SECOND_LEVEL = new Set(["co", "com", "org", "net", "ac", "gov", "edu", "ne", "or"]);

/** Subdomains that say nothing about the brand (docs.github.com is GitHub). */
const GENERIC_SUBDOMAINS = new Set([
  "www", "docs", "doc", "app", "apps", "api", "blog", "dev", "developer", "developers", "help", "support",
  "status", "cdn", "static", "m", "mobile", "en", "beta", "console", "dashboard", "portal", "my", "account",
  "accounts", "login", "auth", "admin", "community", "forum", "forums", "learn", "web", "get", "go",
  "download", "downloads", "news", "store", "shop", "about", "info", "registry",
]);

/** Domains whose obvious key points at the wrong (or no) brand. Values must be slugs. */
const HOST_OVERRIDES: Record<string, string> = {
  "developer.mozilla.org": "mdnwebdocs",
  "twitter.com": "x",
  "ray.so": "raycast",
  "mail.google.com": "gmail",
  "claude.ai": "claude",
  "ui.shadcn.com": "shadcnui",
  "react.dev": "react",
  "reactjs.org": "react",
  "go.dev": "go",
  "golang.org": "go",
  "rust-lang.org": "rust",
  "typescriptlang.org": "typescript",
  "npmjs.com": "npm",
  "youtu.be": "youtube",
  "zed.dev": "zedindustries",
};

/** Marketing-domain affixes: getbootstrap → bootstrap, jestjs → jest, datadoghq → datadog. */
const NAME_PREFIXES = ["get", "use", "try", "join"] as const;
const NAME_SUFFIXES = ["js", "hq", "app", "pkg", "lang", "dev", "io", "db"] as const;

const IPV4 = /^\d{1,3}(?:\.\d{1,3}){3}$/;

/** Lower-cases a hostname and drops a trailing dot and leading `www.`. */
export function normalizeHostname(hostname: string): string {
  return hostname.trim().toLowerCase().replace(/\.$/, "").replace(/^www\d*\./, "");
}

type ParsedHost = { name: string; suffix: string; subs: string[]; platform: boolean };

function parseHost(hostname: string): ParsedHost | null {
  const host = normalizeHostname(hostname);
  if (!host || IPV4.test(host) || host.includes(":")) return null;
  const labels = host.split(".");
  if (labels.length < 2) return null;

  let suffixLength = 1;
  const platform = PLATFORM_SUFFIXES.find((suffix) => host.endsWith(`.${suffix}`));
  if (platform) suffixLength = platform.split(".").length;
  else if (labels.length >= 3 && labels.at(-1)!.length === 2 && COUNTRY_SECOND_LEVEL.has(labels.at(-2)!)) suffixLength = 2;

  const nameIndex = labels.length - suffixLength - 1;
  if (nameIndex < 0) return null;
  return {
    name: labels[nameIndex],
    suffix: labels.slice(nameIndex + 1).join(""),
    // Nearest subdomain first; generic ones (docs, app, www…) carry no brand.
    subs: labels.slice(0, nameIndex).reverse().filter((label) => !GENERIC_SUBDOMAINS.has(label)),
    platform: Boolean(platform),
  };
}

/** The site's own name label: `docs.github.com` → "github", `bbc.co.uk` → "bbc". */
export function hostNameLabel(hostname: string): string | null {
  return parseHost(hostname)?.name ?? null;
}

/** Candidate lookup keys for a hostname, most specific first. */
export function brandKeysForHost(hostname: string): string[] {
  const parsed = parseHost(hostname);
  if (!parsed) return [];
  const { name, suffix, subs, platform } = parsed;

  const keys: string[] = [];
  for (const sub of subs) keys.push(brandKey(name + sub), brandKey(sub + name)); // cloud.google → googlecloud
  for (const sub of subs) keys.push(brandKey(sub)); // firebase.google.com → firebase, webpack.js.org → webpack
  if (!platform) keys.push(brandKey(name + suffix)); // fly.io → flyio, dev.to → devto
  keys.push(brandKey(name));
  for (const prefix of NAME_PREFIXES) if (name.startsWith(prefix) && name.length - prefix.length >= 3) keys.push(brandKey(name.slice(prefix.length)));
  for (const end of NAME_SUFFIXES) if (name.endsWith(end) && name.length - end.length >= 3) keys.push(brandKey(name.slice(0, -end.length)));
  return [...new Set(keys.filter(Boolean))];
}

/** Builds a hostname → slug resolver for one index. */
export function createBrandResolver(index: BrandIconIndex): (hostname: string) => string | null {
  const slugs = new Set(index.slugs);
  const lookup = (key: string) => (slugs.has(key) ? key : (index.aliases[key] ?? null));
  return (hostname) => {
    const host = normalizeHostname(hostname);
    const override = HOST_OVERRIDES[host];
    if (override && slugs.has(override)) return override;
    for (const key of brandKeysForHost(host)) {
      const slug = lookup(key);
      if (slug) return slug;
    }
    return null;
  };
}
